def refs():
    return [{**s, "subject": "science", "observedPattern": "公立學校公開理化題常用門把、扳手、翹翹板、拔釘器與槓桿圖，要求辨認支點、力臂、順逆時針力矩及三類槓桿；本題只改寫能力方向。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-eb-iv-2-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開自然／理化資料僅作力臂、力矩、槓桿平衡與工具分類的能力方向研究；未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與公立學校公開試題能力方向獨立改寫，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-12", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
make(1, "同樣用 30 N 的力推門，甲在距鉸鏈 0.20 m 處，乙在 0.80 m 處且皆垂直門面，誰產生的力矩較大？", {"A": "甲，因為較靠近鉸鏈", "B": "乙，因為力臂較長", "C": "兩者相等，因為施力相同", "D": "無法判斷，力矩沒有方向"}, "B", "力矩＝力×力臂；兩力相同時，乙的 0.80 m 力臂較長，力矩較大。", "固定力的大小與方向，只比較支點到作用線的垂直距離。", ["確認鉸鏈是支點。", "確認兩次施力大小和方向相同。", "比較 0.20 m 與 0.80 m 力臂。", "用力矩公式判斷遠處力矩較大。", "所以選 B。"], "easy"),
make(2, "扳手受力 40 N，若力臂由 0.15 m 增至 0.45 m，力矩變為原來的幾倍？", {"A": "1/3 倍", "B": "1 倍", "C": "3 倍", "D": "9 倍"}, "C", "力固定時力矩與力臂成正比；0.45÷0.15＝3，因此力矩變為 3 倍。", "先確認力不變，再用新舊力臂比值求力矩比。", ["寫出 τ＝Fr。", "比較新舊力臂 0.45 和 0.15。", "計算 0.45÷0.15＝3。", "確認力相同所以比例直接適用。", "故選 C。"], "medium"),
make(3, "一支槓桿左側 20 N 的力作用於 0.30 m 處，右側 0.20 m 處要平衡，右側所需力為何？", {"A": "13 N", "B": "20 N", "C": "30 N", "D": "60 N"}, "C", "平衡時 20×0.30＝F×0.20，故 F＝30 N；短力臂一側需要較大力。", "以支點列順、逆時針力矩相等，再解未知力。", ["算左側力矩 20×0.30＝6 N·m。", "設右側力矩為 F×0.20。", "令兩力矩相等。", "解 0.20F＝6 得 F＝30 N。", "因此選 C。"], "medium"),
make(4, "槓桿上的抗力點位於支點和施力點之間，這是哪一類槓桿？", {"A": "第一類", "B": "第二類", "C": "第三類", "D": "沒有分類"}, "B", "支點—抗力點—施力點的順序表示抗力點在中間，屬第二類槓桿，例如開瓶器。", "用三個位置的相對順序分類，不看工具外形。", ["列出支點、抗力點和施力點。", "找出抗力點位於中間。", "對照三類槓桿定義。", "確認分類不由工具名稱或外觀決定。", "所以答案是 B。"], "easy"),
make(5, "鑷子通常屬於第三類槓桿，主要因為哪個位置在中間？", {"A": "支點", "B": "抗力點", "C": "施力點", "D": "沒有固定點"}, "C", "第三類槓桿的施力點位於支點和抗力點之間，鑷子由手在中間區域施力、尖端夾取物品。", "先找固定彎折處，再排列施力點和抗力點的位置。", ["辨認鑷子的彎折處是支點。", "找出手施力的位置。", "找出尖端接觸物品的抗力點。", "確認施力點位於另外兩者之間。", "故選 C。"], "medium"),
make(6, "某槓桿左側順時針力矩 12 N·m，右側逆時針力矩 7 N·m，淨力矩方向為何？", {"A": "順時針 5 N·m", "B": "逆時針 5 N·m", "C": "順時針 19 N·m", "D": "0 N·m"}, "A", "方向相反的力矩相減：12−7＝5 N·m，較大的順時針力矩勝出。", "先保留方向，再相減大小，不能直接把兩個數字相加。", ["標記順時針 12 和逆時針 7。", "確認方向相反。", "計算 12−7＝5。", "淨方向跟隨較大的順時針力矩。", "所以選 A。"], "medium"),
make(7, "為什麼門把通常遠離鉸鏈，而不是裝在鉸鏈旁？", {"A": "遠處力臂大，用較小力即可產生所需力矩", "B": "遠處會增加門的重量", "C": "鉸鏈旁沒有任何摩擦力", "D": "門把位置不影響轉動"}, "A", "相同需求下，增加力臂可提高力矩，因此可用較小施力轉動門；這是力學效果，不是門把增加力本身。", "把生活設計翻成力矩相等的關係，觀察力臂如何改變所需力。", ["確認門的轉軸是鉸鏈。", "用 τ＝Fr 比較力臂。", "需求力矩固定時，r 增大可使 F 減小。", "排除重量和無摩擦等無關說法。", "因此答案是 A。"], "easy"),
make(8, "一槓桿受兩個大小相等、方向相反但作用線不同的力，可能產生什麼效果？", {"A": "合力為零但合力矩不為零，形成轉動趨勢", "B": "合力和合力矩都必然為零", "C": "一定只向右平移", "D": "兩個力會從物體消失"}, "A", "兩力可使平移合力抵消，但若作用線分離，力矩不能抵消，可能形成力偶造成轉動。", "同時檢查力的向量和以及相對支點的力矩總和。", ["先將兩個反向等力相加，得到合力零。", "檢查兩條作用線是否重合。", "若分離，計算兩力矩方向。", "確認仍有淨轉動效果。", "所以選 A。"], "hard"),
make(9, "若槓桿平衡時右側負載加倍，且力臂不變，左側施力應如何改變才能保持平衡？", {"A": "減半", "B": "不變", "C": "加倍", "D": "變成零"}, "C", "右側力矩加倍，為使逆、順時針力矩仍相等，左側力臂不變時施力也需加倍。", "先寫兩側力矩平衡式，再固定力臂比較力的比例。", ["寫原本 F左r左＝F右r右。", "把右側負載改為原來兩倍。", "因力臂不變，右側力矩變兩倍。", "左側施力也需變兩倍才能抵消。", "故選 C。"], "medium"),
make(10, "下列哪種敘述正確描述槓桿平衡？", {"A": "只要兩端距離相等就一定平衡", "B": "只要兩端力大小相等就一定平衡", "C": "同一支點的順時針力矩總和等於逆時針力矩總和，並且檢查合力", "D": "槓桿只要不動就代表沒有任何力"}, "C", "槓桿轉動平衡需比較兩方向力矩；若要整體靜力平衡，還需檢查合力為零，不能只看距離或力大小。", "把三類常見誤判逐一排除，回到力矩和合力兩項條件。", ["選定同一支點。", "計算順時針力矩總和。", "計算逆時針力矩總和並比較。", "再確認平移合力是否為零。", "因此完整敘述是 C。"], "hard"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    m = {o["id"]: o["text"] for o in q["options"]}
    m["A"], m[target] = m[target], m["A"]
    q["options"] = [{"id": k, "text": m[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["solutionSteps"] = [s.replace("選 A", f"選 {target}").replace("為 A", f"為 {target}") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
